actions.script:
const out = ec.service.sync().name('ironstone.projects.WorkItemImportServices.get#ImportDraft').parameters({importId: importId}).call()
if (!out?.folder || !out.found) { ec.message.addError(ec.l10n.localize('This import is not available; start again from the file')); return }
draft = Object.assign({}, out.draft || {}, fields || {}, {importId: importId, updated: Number(String(ec.user.nowTimestamp))})
ec.resource.getLocationReference(out.folder + '/draft.json').putText(JSON.stringify(draft))

const L = (text) => ec.l10n.localize(text)
const userId = ec.user.userId
if (!userId) { ec.message.addError(L('An import needs a user')); return }
if (!rootWorkEffortId) { ec.message.addValidationError(null, 'rootWorkEffortId', null, L('Choose the project the work items go into'), null); return }
ec.service.sync().name('ironstone.projects.ProjectServices.get#ProjectAccess').parameters({workEffortId: rootWorkEffortId, need: 'update'}).call()
if (ec.message.hasError()) return
let current = importId ? ec.service.sync().name('ironstone.projects.WorkItemImportServices.get#ImportDraft').parameters({importId: importId}).call() : null
if (!current?.found) {
    importId = String(Number(String(ec.user.nowTimestamp))) + '-' + Math.floor(Math.random() * 1e6)
    current = null
}
const hasUpload = workItemFile != null && Number(workItemFile.size || 0) > 0
if (!hasUpload && !current?.fileLocation) { ec.message.addValidationError(null, 'workItemFile', null, L('Choose a CSV file'), null); return }
const folder = `dbresource://ironstone/WorkItemImport/${userId}/${importId}`
let fileName = current?.draft?.fileName || null
const charset = String(characterSet || 'UTF-8').toUpperCase()
if (hasUpload) {
    fileName = String(workItemFile.getName ? workItemFile.getName() : workItemFile.name || 'work-items.csv')
    const read = ec.service.sync().name('mantle.party.ContactImportServices.read#ContactFileText').parameters({contactFile: workItemFile,
        characterSet: charset}).call()
    if (ec.message.hasError()) return
    ec.resource.getLocationReference(`${folder}/source.csv`).putText(String(read?.text ?? ''))
}
const preset = ['jira', 'redmine', 'github', 'generic'].includes(presetId) ? presetId : null
const parsed = ec.service.sync().name('mantle.work.WorkItemImportServices.parse#WorkItemFile').parameters({fileLocation: `${folder}/source.csv`,
    presetId: preset, sampleSize: 3}).call()
if (ec.message.hasError()) return
rowCount = parsed.rowCount || 0
if (!rowCount) { ec.message.addError(L('The file has no work items')); return }
const keep = current?.draft && !hasUpload && (current.draft.chosenPresetId || null) === (presetId || null)
ec.resource.getLocationReference(folder + '/draft.json').putText(JSON.stringify(Object.assign({}, current?.draft || {}, {importId: importId,
    fileName: fileName, presetId: parsed.presetId, chosenPresetId: presetId || null, characterSet: charset, rowCount: rowCount,
    rootWorkEffortId: rootWorkEffortId, columnMapping: keep ? current.draft.columnMapping : (parsed.columnMapping || {}),
    valueMaps: keep ? current.draft.valueMaps : null, estimateUnit: keep ? current.draft.estimateUnit : (parsed.estimateUnit || 'hours'),
    result: null, status: 'source', created: current?.draft?.created || Number(String(ec.user.nowTimestamp))})))

info = null
const L = (text) => ec.l10n.localize(text)
const current = ec.service.sync().name('ironstone.projects.WorkItemImportServices.get#ImportDraft').parameters({importId: importId}).call() || {}
if (!current.found) return
const draft = current.draft
const parsed = ec.service.sync().name('mantle.work.WorkItemImportServices.parse#WorkItemFile').parameters({fileLocation: current.fileLocation,
    presetId: draft.presetId, columnMapping: draft.columnMapping || null, valueMaps: draft.valueMaps || null, sampleSize: 3}).call()
if (ec.message.hasError()) return
const columns = Array.from(parsed.columnList || [])
const mapping = parsed.columnMapping || {}
const columnOptions = columns.map((column) => {
    const samples = Array.from(column.sampleValues || []).map((value) => String(value).substring(0, 24))
    return {key: column.columnName, text: column.columnName + (column.count > 1 ? ' (×' + column.count + ')' : '') + (samples.length ? ' · ' + samples.slice(0, 2).join(', ') : '')}
})
const targets = Array.from(parsed.targetFieldList || []).map((target) => ({fieldName: target.fieldName, description: target.description, column: mapping[target.fieldName] || ''}))
const used = parsed.valueMapsUsed || {type: {}, status: {}, priority: {}}
const values = (kind, limit) => Array.from(parsed.distinctValues?.[kind] || []).slice(0, limit).map((value) => ({value: value, mapped: String(used[kind]?.[value] ?? '')}))
const project = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', draft.rootWorkEffortId || '').one()
const devFlow = project?.statusFlowId === 'WorkEffortDevelopment'
const statusIds = ['WeInPlanning', 'WeApproved', 'WeInProgress'].concat(devFlow ? ['WeInReview', 'WeInTesting'] : []).concat(['WeOnHold', 'WeComplete', 'WeClosed', 'WeCancelled'])
const statusOptions = statusIds.map((id) => ({key: id, text: ec.entity.find('moqui.basic.StatusItem').condition('statusId', id).useCache(true).one()?.description || id}))
let typeOptions = Array.from(ec.service.sync().name('ironstone.projects.ProjectServices.get#WorkItemTypes').parameters({rootWorkEffortId: draft.rootWorkEffortId || null}).call()?.offeredList || [])
        .map((type) => ({key: type.enumId, text: type.label}))
ec.message.clearErrors()
if (!typeOptions.length) typeOptions = [{key: 'WepTask', text: L('Task')}]
const priorityOptions = [1, 2, 3, 4, 5, 6, 7, 8, 9].map((n) => ({key: String(n), text: n + (n <= 3 ? ' · ' + L('high') : n >= 7 ? ' · ' + L('low') : ' · ' + L('normal'))}))
const presets = {jira: 'Jira CSV', redmine: 'Redmine CSV', github: 'GitHub issues CSV', generic: 'CSV'}
info = {draft: draft, columnCount: columns.length, columnOptions: columnOptions, targets: targets, mappedCount: targets.filter((target) => target.column).length,
    presetLabel: presets[parsed.presetId] || parsed.presetId, estimateUnit: draft.estimateUnit || parsed.estimateUnit || 'hours',
    typeValues: values('type', 20), statusValues: values('status', 20), priorityValues: values('priority', 10),
    typeOptions: typeOptions, statusOptions: statusOptions, priorityOptions: priorityOptions, projectName: project?.workEffortName || draft.rootWorkEffortId}

const L = (text) => ec.l10n.localize(text)
running = false
const current = ec.service.sync().name('ironstone.projects.WorkItemImportServices.get#ImportDraft').parameters({importId: importId}).call()
if (!current?.found) { ec.message.addError(L('This import is not available; start again from the file')); return }
const draft = current.draft
if (draft.status === 'done') { result = draft.result; return }
if (draft.status === 'running') { running = true; return }
ec.service.sync().name('ironstone.projects.ProjectServices.get#ProjectAccess').parameters({workEffortId: draft.rootWorkEffortId || '', need: 'update'}).call()
if (ec.message.hasError()) return
const inBackground = background != null ? !!background : Number(draft.rowCount || 0) > 100
if (!inBackground) {
    result = ec.service.sync().name('ironstone.projects.WorkItemImportServices.run#ImportNow').parameters({importId: importId}).call()?.result || null
    return
}
ec.service.sync().name('ironstone.projects.WorkItemImportServices.store#ImportDraft').parameters({importId: importId, fields: {status: 'running',
    error: null, started: Number(String(ec.user.nowTimestamp))}}).call()
if (ec.message.hasError()) return
ec.service.async().name('ironstone.projects.WorkItemImportServices.run#ImportNow').parameters({importId: importId}).call()
running = true

const L = (text) => ec.l10n.localize(text)
const current = ec.service.sync().name('ironstone.projects.WorkItemImportServices.get#ImportDraft').parameters({importId: importId}).call()
if (!current?.found) { ec.message.addError(L('This import is not available; start again from the file')); return }
const draft = current.draft
if (draft.status === 'done') { result = draft.result; return }
const options = draft.options || {}
const fail = (error) => {
    ec.logger.warn(`Work item import ${importId} of ${ec.user.userId} stopped: ${error}`)
    ec.service.sync().name('ironstone.projects.WorkItemImportServices.store#ImportDraft').parameters({importId: importId, fields: {status: 'failed',
        error: error, finished: Number(String(ec.user.nowTimestamp))}}).ignorePreviousError(true).requireNewTransaction(true).call()
}
let out = null
try {
    out = ec.service.sync().name('mantle.work.WorkItemImportServices.import#WorkItems').parameters({fileLocation: current.fileLocation,
        presetId: draft.presetId, columnMapping: draft.columnMapping || null, valueMaps: draft.valueMaps || null, estimateUnit: draft.estimateUnit || null,
        rootWorkEffortId: draft.rootWorkEffortId, createMissing: options.createMissing !== false, existingPolicy: options.existingPolicy || 'skip',
        progressUserId: ec.user.userId, progressKey: importId}).call()
} catch (err) {
    fail(String(err && err.message ? err.message : err)); throw err
}
if (ec.message.hasError()) { fail(ec.message.getErrorsString()); return }
result = {rootWorkEffortId: draft.rootWorkEffortId, rowCount: out.rowCount || 0, createdCount: out.createdCount || 0, updatedCount: out.updatedCount || 0,
    skippedCount: out.skippedCount || 0, failedCount: out.failedCount || 0, failureList: Array.from(out.failureList || []),
    warningList: Array.from(out.warningList || []).slice(0, 500), madeList: Array.from(out.madeList || []),
    resultList: Array.from(out.resultList || []).slice(0, 1000)}
ec.service.sync().name('ironstone.projects.WorkItemImportServices.store#ImportDraft').parameters({importId: importId, fields: {status: 'done', result: result,
    error: null, finished: Number(String(ec.user.nowTimestamp))}}).call()
